sp_widget.client_script:
api.controller = function() {
  /* widget controller */
  var c = this;

  c.anos = c.data.anos || [];
  c.selectedAno = '';

  c.onAnoChange = function() {
    // Emite evento global para que outros widgets escutem
    var event = new CustomEvent('despesaPessoalFiltroAno', {
      detail: { ano: c.selectedAno }
    });
    window.dispatchEvent(event);
  };
};

sp_widget.css:
.filter-header {
  border-radius: 6px;
  background-color: #f3f4f6;
  padding: 1rem;
  margin-bottom: 1rem;
}

.filter-header label {
  margin-right: 0.5rem;
  font-weight: 500;
}

.filter-header select {
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
  border: 1px solid #ccc;
}

sp_widget.script:
(function() {
  // Script para buscar os anos disponíveis na tabela
  var anos = [];
  var ga = new GlideAggregate('x_sded9_portal_t_0_u_despesa_pessoal');
  ga.addAggregate('COUNT');
  ga.groupBy('u_ano');
  ga.query();

  while (ga.next()) {
    anos.push(ga.getValue('u_ano'));
  }

  anos.sort().reverse(); // Do mais recente para o mais antigo

  data.anos = anos;
})();
